def claim_daily_quest_reward_with_firius_tokens(user_id):
    """Atomically claim the base reward plus 5 cumulative Firius Tokens."""
    from data.balance import DAILY_QUEST_REWARD_ITEM_ID, DAILY_QUEST_REWARD_QUANTITY

    db = _db()
    db.reset_daily_quest_if_needed(user_id)
    conn = db.conn
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT progress, target_count, completed, reward_claimed
            FROM user_daily_quests WHERE user_id=?
            """,
            (int(user_id),),
        ).fetchone()
        if not row:
            conn.rollback()
            return {"success": False, "message": "❌ Щоденне завдання не знайдено."}
        progress, target_count, completed, reward_claimed = row
        if not bool(completed):
            conn.rollback()
            return {
                "success": False,
                "message": (
                    "❌ Щоденне завдання ще не виконано.\n\n"
                    f"📈 Прогрес: {int(progress or 0)}/{int(target_count or 0)}"
                ),
            }
        if bool(reward_claimed):
            conn.rollback()
            return {"success": False, "message": "✅ Нагороду за сьогодні вже отримано."}

        base_plan = _plan_stack_addition(
            conn, user_id, DAILY_QUEST_REWARD_ITEM_ID, DAILY_QUEST_REWARD_QUANTITY
        )
        token_plan = _plan_stack_addition(
            conn, user_id, FIRIUS_TOKEN_ITEM_ID, FIRIUS_TOKENS_PER_DAILY_REWARD
        )
        bag_row = conn.execute(
            "SELECT bag_slots FROM users WHERE user_id=?", (int(user_id),)
        ).fetchone()
        used_slots = int(conn.execute(
            "SELECT COUNT(*) FROM inventory WHERE user_id=?", (int(user_id),)
        ).fetchone()[0] or 0)
        capacity = int((bag_row[0] if bag_row else 0) or 0)
        required_slots = base_plan["new_slots"] + token_plan["new_slots"]
        if used_slots + required_slots > capacity:
            conn.rollback()
            return {
                "success": False,
                "code": "bag_full",
                "message": (
                    "🎒 Сумка переповнена.\n\n"
                    "Звільни місце в інвентарі та спробуй забрати нагороду ще раз.\n"
                    "Нічого не було втрачено або частково нараховано."
                ),
            }

        _apply_stack_plan(conn, user_id, base_plan)
        _apply_stack_plan(conn, user_id, token_plan)
        updated = conn.execute(
            "UPDATE user_daily_quests SET reward_claimed=1 "
            "WHERE user_id=? AND completed=1 AND reward_claimed=0",
            (int(user_id),),
        ).rowcount
        if updated != 1:
            raise RuntimeError("Daily reward state changed during claim")
        conn.commit()
        return {
            "success": True,
            "base_item_id": base_plan["item_id"],
            "base_quantity": base_plan["quantity"],
            "firius_token_item_id": FIRIUS_TOKEN_ITEM_ID,
            "firius_token_quantity": FIRIUS_TOKENS_PER_DAILY_REWARD,
            "message": (
                "🎁 Ви отримали нагороду за щоденне завдання!\n\n"
                f"📦 {base_plan['name']} ×{base_plan['quantity']}\n"
                f"🪙 {token_plan['name']} ×{token_plan['quantity']}\n\n"
                "Жетони Фіріуса накопичуються та не зникають наступного дня."
            ),
        }
    except Exception:
        conn.rollback()
        raise

def _apply_stack_plan(conn, user_id, plan):
    for new_quantity, inventory_id in plan["updates"]:
        conn.execute(
            "UPDATE inventory SET quantity=? WHERE id=? AND user_id=?",
            (new_quantity, inventory_id, int(user_id)),
        )
    for quantity in plan["inserts"]:
        conn.execute(
            "INSERT INTO inventory (user_id, item_id, quantity) VALUES (?, ?, ?)",
            (int(user_id), plan["item_id"], quantity),
        )

def claim_daily_quest_reward(user_id):
    """Atomically grant all daily quest rewards and mark the claim."""
    # ROM 17.5.1 ATOMIC DAILY QUEST REWARD
    from data.balance import DAILY_QUEST_REWARDS
    from .inventory import add_item

    quest = get_user_daily_quest(user_id)
    if quest["status"] == "claimed":
        return (False, "⚠️ Ви вже отримали винагороду за сьогодні!", None)
    if not is_daily_quest_complete(user_id):
        return (False, "⚠️ Квест ще не виконано!", None)

    today = get_daily_today_str()
    rewards = {}
    try:
        cursor.execute("BEGIN IMMEDIATE")
        current = cursor.execute(
            "SELECT status FROM user_daily_activity WHERE user_id=? AND daily_key=?",
            (user_id, today),
        ).fetchone()
        if not current or str(current[0]) == "claimed":
            conn.rollback()
            return (False, "⚠️ Винагорода вже отримана або квест недоступний.", None)

        item_results = []
        for item_id, quantity in DAILY_QUEST_REWARDS.get("items", []):
            result = add_item(user_id, item_id, quantity, commit=False)
            if (not result.get("success") or
                    int(result.get("added", 0) or 0) != int(quantity) or
                    int(result.get("lost", 0) or 0) != 0):
                conn.rollback()
                name = result.get("name", f"ID {item_id}")
                reason = result.get("message", "Предмет не вдалося додати.")
                return (False, f"❌ Не вдалося отримати нагороду: {name}. {reason}", None)
            item_results.append((item_id, quantity))

        gold_amount = float(DAILY_QUEST_REWARDS.get("gold", 0) or 0)
        if gold_amount:
            changed = cursor.execute(
                "UPDATE users SET gold=COALESCE(gold,0)+? WHERE user_id=?",
                (gold_amount, user_id),
            ).rowcount
            if changed != 1:
                raise RuntimeError("Не вдалося видати золото щоденного завдання.")
            rewards["gold"] = gold_amount
        if "items" in DAILY_QUEST_REWARDS:
            rewards["items"] = item_results

        changed = cursor.execute(
            """UPDATE user_daily_activity
               SET status='claimed', claimed_at=CURRENT_TIMESTAMP
               WHERE user_id=? AND daily_key=? AND status<>'claimed'""",
            (user_id, today),
        ).rowcount
        if changed != 1:
            raise RuntimeError("Не вдалося зафіксувати отримання нагороди.")
        conn.commit()
        return (True, "✅ Винагорода отримана!", rewards)
    except Exception as error:
        conn.rollback()
        return (False, f"❌ Не вдалося отримати нагороду: {error}", None)

def is_daily_quest_complete(user_id):
    """Перевіряє чи виконано щоденний квест."""
    from data.balance import DAILY_QUEST_REQUIREMENTS

    quest = get_user_daily_quest(user_id)

    if quest["status"] != "active":
        return False

    return (
        quest["total_kills"] >= DAILY_QUEST_REQUIREMENTS["total_kills"] and
        quest["elite_kills"] >= DAILY_QUEST_REQUIREMENTS["elite_kills"]
    )

def reset_daily_quest_if_needed(user_id):
    """Roll the single per-user daily row to today without requiring the bot to stay online."""
    today = get_daily_today_str()
    columns = {str(row[1]) for row in cursor.execute(
        "PRAGMA table_info(user_daily_activity)"
    ).fetchall()}
    if not columns:
        init_daily_quest_system()
        columns = {str(row[1]) for row in cursor.execute(
            "PRAGMA table_info(user_daily_activity)"
        ).fetchall()}

    date_column = next((name for name in (
        "daily_key", "quest_date", "daily_date", "reset_date", "created_date", "date"
    ) if name in columns), None)
    if not date_column:
        return {"success": True, "reset": False, "mode": "no_date_column"}

    row = cursor.execute(
        f"SELECT {date_column} FROM user_daily_activity WHERE user_id=?",
        (int(user_id),),
    ).fetchone()
    if not row:
        return {"success": True, "reset": False, "mode": date_column, "missing": True}
    stored_date = str(row[0] or "")
    if stored_date == str(today):
        return {"success": True, "reset": False, "mode": date_column}

    assignments = []
    params = []
    for name, value in (
        ("progress", 0), ("completed", 0), ("reward_claimed", 0),
        ("total_kills", 0), ("elite_kills", 0), ("pvp_kills", 0),
        ("trades_completed", 0), ("status", "active"), ("claimed_at", None),
        (date_column, today),
    ):
        if name in columns:
            assignments.append(f"{name}=?")
            params.append(value)
    if not assignments:
        return {"success": True, "reset": False, "mode": "no_reset_columns"}
    params.append(int(user_id))
    cursor.execute(
        f"UPDATE user_daily_activity SET {', '.join(assignments)} WHERE user_id=?",
        tuple(params),
    )
    conn.commit()
    return {"success": True, "reset": True, "mode": date_column,
            "from": stored_date, "to": str(today)}

def get_daily_today_str():
    from datetime import date
    return date.today().isoformat()

def add_item(user_id, item_id, quantity=1, durability=100, commit=True):
    """Add items atomically; commit=False leaves final transaction ownership to caller."""
    # ROM 17.5.1 ADD_ITEM TRANSACTION OWNERSHIP
    try:
        user_id = int(user_id)
        item_id = int(item_id)
        quantity = int(quantity)
    except Exception:
        return {"success": False, "name": "Предмет", "added": 0, "lost": 0,
                "message": "❌ Некоректні дані предмета."}
    if quantity <= 0:
        return {"success": False, "name": "Предмет", "added": 0, "lost": 0,
                "message": "❌ Кількість має бути більшою за нуль."}

    item = cursor.execute(
        "SELECT name, COALESCE(max_stack, 1) FROM items WHERE id=?", (item_id,)
    ).fetchone()
    if not item:
        return {"success": False, "name": "Предмет", "added": 0, "lost": quantity,
                "message": "❌ Предмет не знайдено."}
    name = str(item[0] or "Предмет")
    max_stack = max(1, int(item[1] or 1))
    requested = quantity
    savepoint = "rom_add_item_17_5_1"

    try:
        cursor.execute(f"SAVEPOINT {savepoint}")
        capacity = get_bag_capacity(user_id)
        used_slots = get_inventory_used_slots(user_id)
        partial = []
        free_space = 0
        if max_stack > 1 and not _inventory_reserved_ids_for_item(user_id, item_id):
            partial = cursor.execute(
                """SELECT id, quantity FROM inventory
                   WHERE user_id=? AND item_id=? AND quantity>0 AND quantity<?
                   ORDER BY id ASC""",
                (user_id, item_id, max_stack),
            ).fetchall()
            free_space = sum(max(0, max_stack-int(row[1] or 0)) for row in partial)

        new_stacks = _inventory_required_new_stacks(quantity, free_space, max_stack)
        if used_slots + new_stacks > capacity:
            cursor.execute(f"ROLLBACK TO {savepoint}")
            cursor.execute(f"RELEASE {savepoint}")
            return {"success": False, "name": name, "added": 0, "lost": requested,
                    "inventory_id": None, "used_slots": used_slots, "capacity": capacity,
                    "message": "🎒 Сумка переповнена!"}

        first_inventory_id = None
        for inventory_id, current in partial:
            if quantity <= 0:
                break
            current = max(0, int(current or 0))
            moved = min(quantity, max_stack-current)
            if moved:
                cursor.execute(
                    "UPDATE inventory SET quantity=? WHERE id=? AND user_id=? AND item_id=?",
                    (current+moved, int(inventory_id), user_id, item_id),
                )
                if cursor.rowcount != 1:
                    raise RuntimeError("Не вдалося оновити існуючий стак.")
                first_inventory_id = first_inventory_id or int(inventory_id)
                quantity -= moved

        while quantity > 0:
            stack_quantity = min(quantity, max_stack)
            cursor.execute(
                "INSERT INTO inventory (user_id,item_id,quantity,durability) VALUES (?,?,?,?)",
                (user_id,item_id,stack_quantity,durability),
            )
            first_inventory_id = first_inventory_id or int(cursor.lastrowid)
            quantity -= stack_quantity

        cursor.execute(f"RELEASE {savepoint}")
        if commit:
            conn.commit()
        return {"success": True, "name": name, "added": requested, "lost": 0,
                "inventory_id": first_inventory_id,
                "used_slots": get_inventory_used_slots(user_id), "capacity": capacity,
                "message": f"✅ Додано {name} x{requested}"}
    except Exception as error:
        try:
            cursor.execute(f"ROLLBACK TO {savepoint}")
            cursor.execute(f"RELEASE {savepoint}")
        except Exception:
            if commit:
                conn.rollback()
        return {"success": False, "name": name, "added": 0, "lost": requested,
                "inventory_id": None,
                "message": f"❌ Не вдалося додати предмет: {error}"}

def compact_user_item_stacks(user_id, item_id, commit=False, connection=None):
    """Compact safe unreserved stacks for one user/item without changing totals."""
    database = connection or conn
    user_id, item_id = int(user_id), int(item_id)
    item = database.execute("SELECT COALESCE(max_stack,1) FROM items WHERE id=?", (item_id,)).fetchone()
    max_stack = max(1, int(item[0] or 1)) if item else 1
    if max_stack <= 1:
        return {"success": True, "changed": False, "reason": "not_stackable"}
    reserved = set()
    if database.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='inventory_reservations'").fetchone():
        reserved = {int(row[0]) for row in database.execute(
            "SELECT DISTINCT inventory_id FROM inventory_reservations WHERE user_id=? AND COALESCE(quantity,0)>0",
            (user_id,),
        ).fetchall()}
    rows = database.execute(
        "SELECT id,COALESCE(quantity,0) FROM inventory WHERE user_id=? AND item_id=? AND quantity>0 ORDER BY id",
        (user_id,item_id),
    ).fetchall()
    safe = [(int(row[0]),int(row[1] or 0)) for row in rows if int(row[0]) not in reserved]
    if len(safe) <= 1:
        return {"success": True, "changed": False, "reason": "nothing_to_compact"}
    total = sum(quantity for _inventory_id, quantity in safe)
    desired = []
    remaining = total
    while remaining > 0:
        desired.append(min(max_stack, remaining)); remaining -= desired[-1]
    before = [quantity for _inventory_id, quantity in safe]
    if before == desired:
        return {"success": True, "changed": False, "reason": "already_compact"}
    for index, quantity in enumerate(desired):
        database.execute("UPDATE inventory SET quantity=? WHERE id=? AND user_id=? AND item_id=?", (quantity,safe[index][0],user_id,item_id))
    for inventory_id, _quantity in safe[len(desired):]:
        database.execute("DELETE FROM inventory WHERE id=? AND user_id=? AND item_id=?", (inventory_id,user_id,item_id))
    after_total = int(database.execute("SELECT COALESCE(SUM(quantity),0) FROM inventory WHERE user_id=? AND item_id=?",(user_id,item_id)).fetchone()[0] or 0)
    before_total = sum(int(row[1] or 0) for row in rows)
    if after_total != before_total:
        raise RuntimeError("Stack compaction changed total quantity")
    if commit: database.commit()
    return {"success": True, "changed": True, "rows_before": len(safe), "rows_after": len(desired), "freed_rows": len(safe)-len(desired)}
